71	export const remoteUrl = (repo, token) => `https://x-access-token:${token}@github.com/${repo}.git`;
72	
73	// The base branch's remote tip, fetched into this checkout's object store. Read from
74	// the REMOTE, never from HEAD — see the header.
75	export function baseTip(root, remote, base) {
76	  git(root, ['fetch', '--quiet', remote, base]);
77	  return git(root, ['rev-parse', 'FETCH_HEAD']).trim();
78	}
79	
80	// One file's content at a commit, or null when the path does not exist there.
81	export function readAt(root, sha, path) {
82	  try { return git(root, ['show', `${sha}:${path}`]); } catch { return null; }
83	}
84	
85	// Commit `files` ({ path: content }) onto the base tip and push to `branch`,
86	// force — the content is regenerated wholesale each run, so the branch is a
87	// regenerate-not-reconcile surface.
88	export function pushGenerated(root, { remote, baseSha, branch, files, message }) {
89	  const index = join(tmpdir(), `claudinite-deliver-${process.pid}-${Date.now()}.index`);
90	  const plumb = (args, opts) => git(root, args, { ...opts, env: { ...process.env, GIT_INDEX_FILE: index } });
91	  try {
92	    plumb(['read-tree', baseSha]);
93	    for (const [path, content] of Object.entries(files)) {
94	      const blob = git(root, ['hash-object', '-w', '--stdin'], { input: content }).trim();
95	      plumb(['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`]);
96	    }
97	    const tree = plumb(['write-tree']).trim();
98	    const commit = git(root, [
99	      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
100	      'commit-tree', tree, '-p', baseSha, '-m', message,
101	    ]).trim();
102	    git(root, ['push', '--quiet', '--force', remote, `${commit}:refs/heads/${branch}`]);
103	    return commit;
104	  } finally { rmSync(index, { force: true }); }
105	}
106	
107	// Which branch the regenerate lands on and which pull request it updates — THE
108	// EXECUTOR'S DECISION, handed in (docs/PRINCIPLES.md): `branch` is the
109	// one it resolved, `pr` the open pull request it said to amend, or null for a fresh
110	// one on that branch. A named pull request the open list no longer carries was
111	// closed under the run; the branch is still the one to push to, and a new pull
112	// request opens on it.
113	//
114	// With no `branch` handed in — an executor that predates the hand-off — the lane
115	// falls back to what it did on its own: reuse an open pull request whose head
116	// carries `branchPrefix`, else mint `<branchPrefix>/<stamp>`.
117	// @legacy-tolerance advisory:none retire:#1698
118	export function generatedTarget({ pulls, branchPrefix = null, stamp = null, branch = null, pr = null }) {
119	  const open = Array.isArray(pulls) ? pulls : [];
120	  if (branch) {
121	    const named = pr == null ? null : open.find((p) => p.number === Number(pr)) ?? null;
122	    return { branch, pr: named, reused: Boolean(named) };
123	  }
124	  const found = open.find((p) => p.head?.ref?.startsWith(`${branchPrefix}/`)) ?? null;
125	  return { branch: found ? found.head.ref : `${branchPrefix}/${stamp}`, pr: found, reused: Boolean(found) };
126	}
127	
128	// Deliver `files` on a PR that lands itself where the member allows it, on the
129	// branch and pull request the executor resolved (`branch`, `pr` — see
130	// `generatedTarget`): amending an open pull request updates it in place, so a
131	// daily regenerate that runs before yesterday's merged does not stack a second one.
132	//
133	// How the PR lands is land-pr.mjs's business, not the calling task's: the member's
134	// `dailyClaudiniteUpdatesRequirePrReview` (read from the BASE tip — a repo that
135	// declares it gets its PR opened and left for the owner), then the repo's own shape (no PR CI → direct merge; ungated base → verify-then-
136	// land; a gate → arm auto-merge, landing poll as fallback). A PR this run could not
137	// land stays open — the next run rebuilds it from the base, so nothing is lost.
138	//
139	// Returns { branch, number, reused, delivery, merged }.
