const targetBranch = process.env.CLAUDINITE_TARGET_BRANCH || null;
const targetPr = process.env.CLAUDINITE_TARGET_PR || null;
// A CONVERGE WITH NO TARGET HAS NOWHERE TO DELIVER. The worker had a path of its
// own — dispose of the incumbent it found by branch prefix, mint a dated branch —
// and it was the second decision site #1695 removed; #1698 removed the fallback
// once every converging member ran the executor that hands the target in. So an
// absent one is a member whose executor is stale, which its own next converge
// fixes: say that, and stop before the clone rather than deliver where nothing is
// looking. A REHEARSAL is exempt — it restores the tree and delivers nothing, and
// the canary gate drives this worker with no executor at all.
if (!rehearsalRef && !targetBranch) {
  throw new Error('no CLAUDINITE_TARGET_BRANCH — this repo\'s executor predates the target hand-off (#1695);'
    + ' its next converge brings the one that sets it');
}

