// One override, one direction: a repo that asked for review gets its PR opened and
// left; every other repo — the normal shape, the key absent — has it landed.
const delivery = deliveryFor(declaration);

// THE TARGET. Which branch this run pushes to, and which pull request it delivers
// on, is the executor's decision: the task declares
// `amend_existing_or_create_new_pr`, the executor resolved it before this
// subprocess started — this cycle's own branch where the last one's pull request
// is gone or conflicted, that pull request's own branch otherwise — and handed
// both in. Nothing here reads the open pull requests or picks a name.
//
// Reusing it is what keeps a member that cannot land from accumulating a line of
// obsolete pull requests, one a night: the converge is a full recompute from the
// base, so the force-push below REWRITES the open one into this cycle's answer
// rather than stacking a second delivery beside it.
const targetBranch = process.env.CLAUDINITE_TARGET_BRANCH || null;
const targetPr = process.env.CLAUDINITE_TARGET_PR || null;
// A CONVERGE WITH NO TARGET HAS NOWHERE TO DELIVER. This worker used to dispose of
// an incumbent it found by branch prefix and mint a dated branch of its own — the
// second decision site #1695 removed, held only for the window in which a member's
// vendored executor predated the hand-off. This task declares an outcome that opens
// a pull request, so a current executor always resolves a branch: an absent one is
// an executor too old to have set it, and delivering on a branch it is not watching
// is worse than saying so. A REHEARSAL is exempt — it restores the tree and delivers
// nothing, and the canary gate drives this worker with no executor at all.
if (!rehearsalRef && !targetBranch) {
  console.error('claudinite-needs-human: action — the mount is too old to converge itself:'
    + ' re-baseline it against the canon (basics/baselining)');
  throw new Error('no CLAUDINITE_TARGET_BRANCH — this repo\'s executor predates the target hand-off (#1695)');
}

