50	// owns it — the engine's own, or one pack's — so both homes count (#768).
51	const MIGRATION_RECORD = /^(engine|packs\/[^/]+)\/migrations\/\d{4}-\d{2}-\d{2}-[^/]+\//;
52	const MIGRATIONS = '<engine|packs/*>/migrations/<date>-<name>/';
