66	// pack does either — so both converge green whatever this surface does. #1750 dropped
67	// nine names from converge-wiring.mjs and left missingbulb/Shepherd#477 parked.
68	//
69	// A RE-EXPORT SHIM IS THE DISCHARGE, and it needs no mechanism of its own: a name
70	// still exported is not a removal. #1750 already gave three of its nine names exactly
71	// that. The other two answers stay available for a name that genuinely must go.
72	//
73	// Measured before widening, over the 60 most recent first-parent commits on main:
74	// 4 commits would have fired (1 engine, 3 packs). `packs/**` is in because the surface
75	// is structurally identical — Shepherd's fleet-issues-snapshot worker reaches four
76	// modules under `shared/packs/`.
77	const VENDORED_MODULE = /^(engine|packs)\//;
78	
79	// The names a module exports, by every form the corpus writes: a declaration
80	// (`export const|let|var|function|async function|class NAME`) and an export list
81	// (`export { a, b as c }`, where the exported name is what an importer must write).
82	// `export default` is out: a default is imported by position, not by name.
83	//
84	// Comments are stripped first — a commented-out export is not a contract, and the
85	// engine's own string-aware remover is what tells a `//` inside a string from one that
86	// opens a comment.
87	const EXPORT_DECL = /^\s*export\s+(?:async\s+)?(?:function\*?|const|let|var|class)\s+([A-Za-z_$][\w$]*)/gm;
88	const EXPORT_LIST = /^\s*export\s*\{([^}]*)\}/gm;
89	export function exportedNames(text) {
90	  const names = new Set();
91	  if (typeof text !== 'string') return names;
92	  const src = stripComments(text);
93	  for (const m of src.matchAll(EXPORT_DECL)) names.add(m[1]);
94	  for (const m of src.matchAll(EXPORT_LIST)) {
95	    for (const part of m[1].split(',')) {
96	      const spec = part.trim();
97	      if (!spec) continue;
98	      const renamed = /\bas\s+([A-Za-z_$][\w$]*)$/.exec(spec);
99	      names.add(renamed ? renamed[1] : spec.split(/\s+/)[0]);
100	    }
101	  }
102	  return names;
103	}
104	
105	// Present in the base, absent from the head. A head that cannot be read is the file
106	// deleted — every name it exported is gone, which is the shape a whole-module removal
107	// takes and the one a diff-line rule cannot see. A base that cannot be read is a file
108	// this change ADDED, and an addition removes nothing.
109	export function removedExports(file, head, base) {
110	  if (!VENDORED_MODULE.test(file) || MIGRATION_RECORD.test(file)) return [];
111	  if (typeof base !== 'string') return [];
112	  const now = exportedNames(head);
113	  return [...exportedNames(base)].filter((name) => !now.has(name));
114	}
115	
116	// A comment is inert on every surface this rule watches: a member vendors the bytes
117	// verbatim and nothing reads the prose in them, so rewriting one carries nobody
118	// anywhere and asking for a migration record would be the cried-wolf firing this
119	// rule is narrowed to avoid. Both sides must be readable to reach that conclusion —
120	// an unreadable file stays a contract surface, so the fail-safe answer is the one a
121	// missing file gets.
122	//
123	// `#` only opens a comment at line start or after whitespace, which is what keeps a
124	// `#` inside a YAML scalar (a URL fragment, an `echo 'a # b'`) a real character.
125	function stripYamlComments(text) {
126	  return text.split('\n').map((line) => {
127	    let quote = null;
128	    for (let i = 0; i < line.length; i += 1) {
129	      const c = line[i];
130	      if (quote) { if (c === quote) quote = null; continue; }
131	      if (c === '"' || c === "'") { quote = c; continue; }
132	      if (c === '#' && (i === 0 || /\s/.test(line[i - 1]))) return line.slice(0, i);
133	    }
134	    return line;
135	  }).join('\n');
136	}
137	
138	const normalize = (text) => text.split('\n').map((l) => l.trimEnd()).filter(Boolean).join('\n');
139	
140	// `strip` is the language's own comment remover — YAML's above for a stub, the
141	// engine's string-aware JS one for the schema module.
142	function commentOnly(head, base, strip) {
143	  if (typeof head !== 'string' || typeof base !== 'string') return false;
144	  return normalize(strip(head)) === normalize(strip(base));
145	}
146	
147	// The contract surfaces this change touched, and why each counts. Pure over the
148	// changed-file list plus a head and a base reader, so the whole decision is
149	// testable with no git.
150	export function contractChanges(changed, read, readBase = () => null) {
151	  const out = [];
152	  if (changed.includes(SCHEMA) && !commentOnly(read(SCHEMA), readBase(SCHEMA), stripComments)) {
153	    out.push({ file: SCHEMA, what: 'the pack manifest vocabulary — every consumer local pack is validated against it' });
154	  }
155	  for (const stub of STUBS) {
156	    if (changed.includes(stub) && !commentOnly(read(stub), readBase(stub), stripYamlComments)) {
157	      out.push({ file: stub, what: 'a workflow stub — every member vendors it verbatim' });
158	    }
159	  }
160	  for (const file of changed) {
161	    // A rule module that BECAME blocking in this change — either newly added, or
162	    // promoted from advisory. That transition is the one that turns a green member
163	    // red without the member changing at all. A rule already blocking at the base
164	    // asked nothing new of anyone, so editing its wording, its `doc` pointer or its
165	    // logic is an ordinary pack edit and stays out of scope: firing on those would
166	    // make every touch of a blocking rule a migration question, which is the
167	    // cried-wolf failure this rule is built to avoid.
168	    if (!/\.mjs$/.test(file) || /\.test\.mjs$/.test(file) || file.startsWith('engine-tests/')) continue;
169	    // A rule in the canon's OWN local packs reaches no consumer by construction:
170	    // the vendor set carries engine/ and packs/, never .claudinite/local/, so such a
171	    // rule runs in exactly one repo — this one — and its severity asks nothing of
172	    // anybody else. Firing here would demand a migration for a change no member can
173	    // even see, which is the cried-wolf failure the narrowing above exists to avoid.
174	    if (file.startsWith(`${LOCAL_PACKS}/`)) continue;
175	    const isBlockingRule = (text) => Boolean(text)
176	      && /severity:\s*'blocking'/.test(text)
177	      && /^\s*const rule = \{/m.test(text);
178	    if (isBlockingRule(read(file)) && !isBlockingRule(readBase(file))) {
179	      out.push({ file, what: 'a rule that became blocking — a severity a member did not ask for turns it red overnight' });
180	    }
181	    // One file, one reason: a module reported already — the schema, a stub, a rule
182	    // that just became blocking — asks the author for the same record or fixture, and
183	    // a second entry for it would only crowd the one this rule reports.
184	    if (out.some((entry) => entry.file === file)) continue;
185	    const gone = removedExports(file, read(file), readBase(file));
186	    if (gone.length) {
187	      out.push({
188	        file,
189	        what: `an export a member's local pack may import — ${gone.join(', ')} — that this change removes`,
190	      });
191	    }
192	  }
193	  return out;
194	}
195	
196	// Did this change ALSO carry consumers across? Either answer is enough.
197	export function carriesConsumers(changed) {
198	  return {
199	    migration: changed.some((f) => MIGRATION_RECORD.test(f)),
200	    fixture: changed.includes(FIXTURES),
201	  };
202	}
203	
204	const rule = {
205	  id: 'consumer-safe-change',
206	  severity: 'blocking',
207	  scope: 'work',
208	  description: 'A change to a contract consumers hold a copy of ships a migration record or a rehearsal fixture',
209	  doc: 'consumer-safe-changes.md',
210	  why: 'canon CI cannot see a consumer — the canon\'s own packs are always already migrated, so a change that breaks every member passes it green (#555 did exactly that)',
211	
212	  run(work) {
213	    const changed = work.changedFiles ?? [];
214	    if (!changed.length) return [];
215	    const touched = contractChanges(changed, (f) => work.read(f), (f) => work.readBase(f));
216	    if (!touched.length) return [];
217	    const carried = carriesConsumers(changed);
218	    if (carried.migration || carried.fixture) return [];
219	
220	    const first = touched[0];
221	    return [finding(rule, {
222	      file: first.file,
223	      what: `this change touches ${first.what}, but carries no migration record and no rehearsal fixture`,
224	      fix: `add a record under ${MIGRATIONS} that moves members across, OR a shape in ${FIXTURES} that proves a consumer `
225	        + 'still converges green — then say in the PR which one you chose and why. If the change is genuinely additive, '
226	        + 'the fixture is the honest answer; if it renames or requires something, only a record will move the fleet. '
227	        + 'For a removed export, a re-export shim at the old name is the third and usually the right one.',
228	    })];
229	  },
230	};
231	
232	export default rule;
