1	// Deliver GENERATED files on a pull request that lands itself — the write half of
2	// an agentless task whose whole output is a regenerated file.
3	//
4	// It exists because two tasks need exactly this and must not each grow their own
5	// copy: the per-repo skill-usage fold and the fleet-enforcer's cross-repo aggregate both
6	// recompute a `*.GENERATED.json` from scratch and want it landed without a human in
7	// the loop. (the update runner's own delivery is deliberately NOT folded in here: it
8	// commits a whole working tree from a checkout it converged in place — a
9	// different job that happens to end in a PR too. What the two DO share — every
10	// nuance of actually landing the PR under the member's `maintenance.delivery` and
11	// the repo's own shape — lives in land-pr.mjs, and both call it.)
12	//
13	// Two properties everything here is shaped around:
14	//
15	//   NOTHING TOUCHES THE CHECKOUT. One executor run drains several items from ONE
16	//   checkout, so a task that checks a branch out hands the next one a tree it did not
17	//   expect.
18	//   Every write goes through git plumbing (hash-object / read-tree into a throwaway
19	//   index / write-tree / commit-tree / push), against the fetched base tip — HEAD,
20	//   the index and the working tree are never touched, and there is nothing to clean
21	//   up if the run dies.
22	//
23	//   THE BASE IS THE ONLY AUTHORITY. Both the prior state a generator reads and the
24	//   tree it builds on come from the remote base branch, never from local HEAD. A
25	//   previous run's PR still sitting open is simply rebuilt from the base, so a
26	//   stateless generator stays idempotent no matter how many runs stack up. The
27	//   member's delivery preference is read from the base too, for the same reason.
28	//
29	// Idempotence is the caller's to keep: pass files whose content is a pure function of
30	// the inputs, and compare against `readAtBase` before calling — an identical
31	// recompute should open nothing at all.
32	
33	import { execFileSync } from 'node:child_process';
34	import { rmSync } from 'node:fs';
35	import { tmpdir } from 'node:os';
36	import { join } from 'node:path';
37	import { deliveryForText, pullCreateError, landDelivery } from './land-pr.mjs';
38	import { SETTINGS_FILES } from '../../engine/settings-file.mjs';
39	import { withTaskTrailer } from './task-trailer.mjs';
40	
41	const API = 'https://api.github.com';
42	
43	const git = (root, args, opts = {}) => execFileSync('git', ['-C', root, ...args], {
44	  encoding: 'utf8',
45	  // A generated file can be large, and a `git show` of one easily tops spawn's
46	  // default 1 MiB buffer — which fails as a truncated read, not as an error.
47	  maxBuffer: 256 * 1024 * 1024,
48	  // stdin is 'pipe' exactly when there is input to pipe: an explicit 'ignore' with an
49	  // `input` set silently feeds the child NOTHING, and `hash-object --stdin` then
50	  // cheerfully writes the empty blob — a wrong answer, not an error.
51	  stdio: [opts.input === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'],
52	  ...opts,
53	});
54	
55	async function gh(token, path, { method = 'GET', body } = {}) {
56	  const res = await fetch(`${API}${path}`, {
57	    method,
58	    headers: {
59	      authorization: `Bearer ${token}`,
60	      accept: 'application/vnd.github+json',
61	      'x-github-api-version': '2022-11-28',
62	      ...(body ? { 'content-type': 'application/json' } : {}),
63	    },
64	    body: body ? JSON.stringify(body) : undefined,
65	  });
66	  let json = null;
67	  try { json = await res.json(); } catch { /* empty body */ }
68	  return { status: res.status, json };
69	}
70	
71	export const remoteUrl = (repo, token) => `https://x-access-token:${token}@github.com/${repo}.git`;
72	
73	// The base branch's remote tip, fetched into this checkout's object store. Read from
74	// the REMOTE, never from HEAD — see the header.
75	export function baseTip(root, remote, base) {
76	  git(root, ['fetch', '--quiet', remote, base]);
77	  return git(root, ['rev-parse', 'FETCH_HEAD']).trim();
78	}
79	
80	// One file's content at a commit, or null when the path does not exist there.
81	export function readAt(root, sha, path) {
82	  try { return git(root, ['show', `${sha}:${path}`]); } catch { return null; }
83	}
84	
85	// Commit `files` ({ path: content }) onto the base tip and push to `branch`,
86	// force — the content is regenerated wholesale each run, so the branch is a
87	// regenerate-not-reconcile surface.
88	export function pushGenerated(root, { remote, baseSha, branch, files, message }) {
89	  const index = join(tmpdir(), `claudinite-deliver-${process.pid}-${Date.now()}.index`);
90	  const plumb = (args, opts) => git(root, args, { ...opts, env: { ...process.env, GIT_INDEX_FILE: index } });
91	  try {
92	    plumb(['read-tree', baseSha]);
93	    for (const [path, content] of Object.entries(files)) {
94	      const blob = git(root, ['hash-object', '-w', '--stdin'], { input: content }).trim();
95	      plumb(['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`]);
96	    }
97	    const tree = plumb(['write-tree']).trim();
98	    const commit = git(root, [
99	      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
100	      'commit-tree', tree, '-p', baseSha, '-m', message,
101	    ]).trim();
102	    git(root, ['push', '--quiet', '--force', remote, `${commit}:refs/heads/${branch}`]);
103	    return commit;
104	  } finally { rmSync(index, { force: true }); }
105	}
106	
107	// Which branch the regenerate lands on and which pull request it updates — THE
108	// EXECUTOR'S DECISION, handed in (docs/PRINCIPLES.md): `branch` is the
109	// one it resolved, `pr` the open pull request it said to amend, or null for a fresh
110	// one on that branch. A named pull request the open list no longer carries was
111	// closed under the run; the branch is still the one to push to, and a new pull
112	// request opens on it.
113	//
114	// The branch is REQUIRED. The lane used to reuse an open pull request whose head
115	// carried a prefix and mint `<prefix>/<stamp>` where it found none — a second
116	// decision site beside the executor's, held only while a member's vendored executor
117	// could predate the hand-off (#1698). An outcome that opens a pull request always
118	// resolves one, so an absent branch is a caller the executor is not driving, and
119	// delivering on a branch nothing is watching is worse than saying so.
120	export function generatedTarget({ pulls, branch = null, pr = null }) {
121	  if (!branch) {
122	    throw new Error('no branch to deliver on — the executor resolves it and hands it in as CLAUDINITE_TARGET_BRANCH');
123	  }
124	  const open = Array.isArray(pulls) ? pulls : [];
125	  const named = pr == null ? null : open.find((p) => p.number === Number(pr)) ?? null;
126	  return { branch, pr: named, reused: Boolean(named) };
127	}
128	
129	// Deliver `files` on a PR that lands itself where the member allows it, on the
130	// branch and pull request the executor resolved (`branch`, `pr` — see
131	// `generatedTarget`): amending an open pull request updates it in place, so a
132	// daily regenerate that runs before yesterday's merged does not stack a second one.
133	//
134	// How the PR lands is land-pr.mjs's business, not the calling task's: the member's
135	// `dailyClaudiniteUpdatesRequirePrReview` (read from the BASE tip — a repo that
136	// declares it gets its PR opened and left for the owner), then the repo's own shape (no PR CI → direct merge; ungated base → verify-then-
137	// land; a gate → arm auto-merge, landing poll as fallback). A PR this run could not
138	// land stays open — the next run rebuilds it from the base, so nothing is lost.
139	//
140	// Returns { branch, number, reused, delivery, merged }.
141	export async function deliverGeneratedRenamed({ root, repo, base, token, branch: targetBranch = null, pr: targetPr = null, files, title, body, message, task = null, log = console.log }) {
142	  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);

